def backfill_manual_skill_evidence(apps, schema_editor):
    """Create source='manual' evidence for every existing CandidateSkill.

    Pre-3C CandidateSkill rows predate provenance tracking and cannot be
    reliably attributed to resume vs manual entry, so they are labeled
    'manual'. This establishes the evidence invariant for existing rows;
    all production writers going forward must use api.evidence helpers.
    """
    CandidateSkill = apps.get_model("api", "CandidateSkill")
    CandidateSkillEvidence = apps.get_model("api", "CandidateSkillEvidence")

    for candidate_skill in CandidateSkill.objects.select_related("skill").iterator():
        CandidateSkillEvidence.objects.get_or_create(
            candidate_id=candidate_skill.candidate_id,
            skill_id=candidate_skill.skill_id,
            source="manual",
            defaults={"detail": {}},
        )


